namespace ghidra.file.formats.android.vdex;




using ghidra.app.util.bin;
using ghidra.file.formats.android.cdex;
using ghidra.file.formats.android.dex.format;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.annotations;
using ghidra.formats.gfilesystem.factory;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

/* @FileSystemInfo(type = "androidvdex", description = "Android VDEX (for extracting embedded DEX files)", factory = typeof(GFileSystemBaseFactory)) */
public class VdexFileSystem : GFileSystemBase {

	private VdexHeader header;
	private List<GFile> listing = new();

	public VdexFileSystem(string fileSystemName, ByteProvider provider) : base(fileSystemName, provider)
    {
	}

	/* @Override */
	public bool isValid(TaskMonitor monitor)
    {
		try {
			byte[] magicBytes = provider.readBytes(0, VdexConstants.MAGIC.length());
			return VdexConstants.MAGIC.equals(new string(magicBytes));
		}
		catch (Exception e) {
			// ignore...
		}
		return false;
	}

	/* @Override */
	public void open(TaskMonitor monitor)
    {
		monitor.setMessage("Parsing VDEX header...");
		BinaryReader reader = new BinaryReader(provider, true /* TODO always LE??? */ );
		try {
			header = VdexHeaderFactory.getVdexHeader(reader);
			header.parse(reader, monitor);

			for (int i = 0; i < header.getDexHeaderList().size(); ++i) {
				monitor.checkCancelled();
				DexHeader dexHeader = header.getDexHeaderList().get(i);
				string name =
					((dexHeader is CDexHeader) ? "cdex" + "_" + i : "classes" + i + ".dex");
				GFile file = GFileImpl.fromPathString(this, root, name, null, false,
					Integer.toUnsignedLong(dexHeader.getFileSize()));
				listing.add(file);
			}
		}
		catch (UnsupportedVdexVersionException e) {
			throw new IOException(e);
		}
	}

	/* @Override */
	public void close()
    {
		base.close();
		header = null;
		listing.clear();
	}

	/* @Override */
	public List<GFile> getListing(GFile directory)
    {
		if (directory == null || directory.equals(root)) {
			return listing;
		}
		return Collections.emptyList();
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor)
    {
		int index = listing.indexOf(file);
		if (index < 0) {
			throw new IOException("Unknown file: " + file);
		}
		DexHeader dexHeader = header.getDexHeaderList().get(index);
		long startIndex = header.getDexStartOffset(index);
		return new ByteProviderWrapper(provider, startIndex,
			Integer.toUnsignedLong(dexHeader.getFileSize()), file.getFSRL());
	}

}
